mapper.update:
UPDATE kids_own.tb_cm_m_conts
   SET rls_yn   = #{rlsYn}
     , conts_cn = #{contsCn}
     , mdfr_id  = #{mdfrId}
     , mdfcn_dt = NOW()
 WHERE rvsn_no = #{rvsnNo}
   AND bbs_id  = #{bbsId}

UPDATE kids_own.tb_cm_m_conts
   SET rls_yn = 'Y'
 WHERE rvsn_no = #{rvsnNo}
   AND del_yn  = 'N'
   AND bbs_id  = #{bbsId}

UPDATE kids_own.tb_cm_m_conts
   SET del_yn   = 'Y'
     , mdfcn_dt = NOW()
 WHERE rvsn_no = #{rvsnNo}
   AND bbs_id  = #{bbsId}
